  estimated_minutes = excluded.estimated_minutes, content = excluded.content;

insert into public.mission_keys (mission_id, steps, debrief)
select id, '{"s1":{"correct":"a","explanation":"Documenti d''identità e biometria (selfie) non si ''revocano'': l''esposizione dura nel tempo.","senior":"Classifico subito come incidente con dati personali: coinvolgo HR e, se previsto dalle procedure, il DPO per valutare gli obblighi in materia di protezione dei dati."},"s2":{"correct":"a","explanation":"Il dominio e la policy dichiarata dall''ente sono gli elementi più solidi in assenza di header.","senior":"Cito sempre la fonte ufficiale sul comportamento dell''ente: rende il verdetto verificabile da chiunque."},"s3":{"correct":"b","explanation":"Minimizzazione: si registra ciò che serve all''indagine. Copie di documenti della vittima aumentano il rischio senza aggiungere valore.","senior":"Nel caso scrivo ''esposti: carta d''identità, selfie, dati anagrafici'' con data e ora. Le copie restano dove sono già (purtroppo nelle mani dei criminali), non le moltiplico."},"s4":{"explanation":"Confronta con il senior.","senior":"Denuncia alla Polizia Postale; monitorare l''identità digitale e l''area personale INPS per variazioni (IBAN, recapiti); avvisare la banca; diffidare di contatti successivi che chiedono altri dati; conservare l''SMS. A tutti: l''INPS non manda link via SMS."}}'::jsonb, '{"summary":"Hai gestito un caso di furto d''identità applicando la minimizzazione dei dati: competenza preziosa per un profilo giuridico.","lessons":["Smishing istituzionale = incidente con dati personali quando la vittima ha caricato documenti.","Minimizza i dati personali nel fascicolo.","Le fonti ufficiali dell''ente rendono il verdetto solido."],"next":["Leggi la pagina INPS ''Vademecum antitruffe'' e confrontala con le tue raccomandazioni."]}'::jsonb from public.missions where slug = 'inps-smishing-documenti'
on conflict (mission_id) do update set steps = excluded.steps, debrief = excluded.debrief;

-- 02-real-cases.json · infostealer-ordine-fattura
insert into public.missions (slug, kind, sort_order, title, summary, difficulty, category, roles, estimated_minutes, content)
values ('infostealer-ordine-fattura', 'real_case', 12, 'Infostealer nell''allegato ''ordine'': FormBook, Remcos, AgentTesla', 'Le famiglie malware più diffuse in Italia arrivano quasi sempre come allegati a tema ordini, fatture e preventivi. Analisi di un malspam B2B e valutazione dell''impatto.', 'intermediate', 'security_incident_analysis',
        array['CTI Analyst', 'Cybersecurity Analyst']::text[], 45, '{"request":{"from":"Ufficio Acquisti (scenario di esercitazione)","channel":"Ticket helpdesk","text":"Un fornitore nuovo ci ha mandato un ordine in allegato. Il collega ha aperto l''allegato ma non si vedeva niente, allora l''ha riaperto. Ora il PC è lento. È normale?"},"context":"È lo scenario più comune nelle aziende italiane. L''email è una ricostruzione didattica; famiglie malware, temi ed esche sono quelli riportati dal CERT-AGID e dai report settimanali dei vendor.","dossier":{"phenomenon":"Malspam con allegati compressi (archivi .rar, .zip, immagini disco) a tema ordini, fatture, preventivi e bonifici, che installano infostealer e RAT: malware che rubano credenziali salvate, cookie di sessione e dati dal computer.","figures":[{"text":"Nel 2025 FormBook è stato il malware più diffuso in Italia, seguito da Remcos e AgentTesla; gli infostealer si sono confermati la tipologia più ricorrente.","source":1},{"text":"Nel 2024 il primo posto era di AgentTesla (32 campagne), seguito da FormBook (26) e Remcos (18).","source":2},{"text":"I monitoraggi settimanali dei vendor riportano esche ricorrenti: ordini, fatture, pagamenti, preventivi e bonifici (fonte secondaria, non verificata dal CERT-AGID).","source":3}],"how_it_works":[{"step":"Email B2B credibile con allegato compresso (''ordine'', ''preventivo'')","technique":"T1566.001"},{"step":"L''utente apre l''allegato e avvia l''eseguibile nascosto","technique":"T1204.002"},{"step":"Il malware è offuscato per eludere l''antivirus","technique":"T1027"},{"step":"Furto di credenziali dai browser e dai client email","technique":"T1555.003"},{"step":"Invio dei dati all''attaccante (spesso via SMTP, FTP, HTTP o Telegram)","technique":"T1071"}],"red_flags":["Allegato compresso o con doppia estensione da mittente nuovo","L''allegato ''non si apre'' o non mostra nulla (comportamento tipico dei dropper)","Richiesta di aprire con urgenza un ordine non atteso"],"impact":"Furto delle credenziali salvate (email, VPN, gestionali, banca): diventano la porta d''ingresso per frodi, BEC e ransomware successivi.","defenses":["Isolare il PC dalla rete e coinvolgere chi gestisce gli endpoint","Cambiare da un altro dispositivo tutte le password salvate e invalidare le sessioni","Bloccare gli allegati compressi/eseguibili da mittenti esterni"]},"materials":[{"type":"sample","sample_key":"real-malspam-ordine","label":"Ricostruzione didattica del malspam (domini fittizi)"}],"steps":[{"id":"s1","title":"Apri il caso come incidente","instruction":"Crea un caso Security Incident Analysis con priorità alta, collegalo e scrivi l''obiettivo.","module":{"href":"/investigations/new?category=security_incident_analysis&title=Allegato%20ordine%20aperto%20-%20possibile%20infostealer","label":"Nuovo caso"},"think":["L''allegato è stato aperto due volte: devo presumere la compromissione?","Qual è la prima azione di contenimento?"],"check":{"type":"objective","min":40},"quiz":{"type":"single","prompt":"Qual è la prima azione corretta?","options":[{"value":"a","label":"Riavviare il PC per vedere se si risolve"},{"value":"b","label":"Isolare il PC dalla rete e avvisare chi gestisce gli endpoint, senza spegnerlo"},{"value":"c","label":"Cancellare l''email dalla casella"}]}},{"id":"s2","title":"Analizza il messaggio e l''allegato (senza aprirlo)","instruction":"Analizza la ricostruzione nel Phishing Lab, salva l''analisi sul caso con verdetto e registra gli IOC.","module":{"href":"/phishing?sample=real-malspam-ordine","label":"Phishing Lab"},"think":["Cosa mi dice il nome dell''allegato?","Cosa può fare l''IT con l''hash del file?"],"check":{"type":"phishing","with_verdict":true},"quiz":{"type":"single","prompt":"Perché l''utente ''non vedeva niente'' aprendo l''allegato?","options":[{"value":"a","label":"Il file era corrotto"},{"value":"b","label":"È tipico dei dropper: eseguono il malware in background senza mostrare un documento"},{"value":"c","label":"Mancava un programma per aprirlo"}]}},{"id":"s3","title":"Ricostruisci la sequenza","instruction":"Aggiungi in timeline almeno 3 eventi: ricezione, prima apertura, seconda apertura/segnalazione.","module":{"href":"/investigations/{case}?tab=timeline","label":"Timeline"},"think":["Da quanto tempo il malware potrebbe essere attivo?","Quali credenziali erano salvate su quel PC?"],"check":{"type":"timeline","min":3},"quiz":{"type":"single","prompt":"Perché la finestra temporale è importante in un caso di infostealer?","options":[{"value":"a","label":"Delimita il periodo in cui le credenziali possono essere state sottratte e usate"},{"value":"b","label":"Serve solo per il report"}]}},{"id":"s4","title":"Mappa la catena d''attacco","instruction":"Mappa almeno 2 tecniche ATT&CK della catena (consegna ed esecuzione come fatti; furto di credenziali come ipotesi finché non c''è un''analisi dell''endpoint).","module":{"href":"/investigations/{case}?tab=attack","label":"Scheda ATT&CK"},"think":["Cosa ho osservato e cosa deduco dal tipo di malware?"],"check":{"type":"attack","min":2},"quiz":{"type":"single","prompt":"T1555.003 (credenziali dai browser) va mappata come:","options":[{"value":"fact","label":"Fatto verificato"},{"value":"hyp","label":"Ipotesi con confidenza moderata, da confermare con l''analisi dell''endpoint"}]}},{"id":"s5","title":"Report di incidente","instruction":"Crea il report (Cyber Threat Intelligence o Phishing Investigation) con contenimento, reset credenziali, indicatori e limiti; finalizzalo.","module":{"href":"/reports/new?case={case}","label":"Nuovo report"},"think":["Quali password vanno cambiate e da quale dispositivo?"],"check":{"type":"report","status":"final"},"quiz":{"type":"text","prompt":"Scrivi le 3 azioni più urgenti in ordine di priorità.","min_length":80}}],"sources":[{"title":"Evoluzione delle campagne malevole in Italia: i numeri nel 2025","publisher":"Cybersecurity360 su dati CERT-AGID (fonte secondaria)","url":"https://www.cybersecurity360.it/news/evoluzione-delle-campagne-malevole-in-italia-i-numeri-nel-2025/","date":"2026"},{"title":"Report riepilogativo CERT-AGID 2024","publisher":"AgID","url":"https://www.agid.gov.it/sites/agid/files/2025-01/Report_Riepilogativo_Cert-AgID_2024.pdf","date":"gennaio 2025"},{"title":"Archivio news malspam in Italia","publisher":"TG Soft (vendor, fonte secondaria)","url":"https://www.tgsoft.it/news/news_archivio.asp?id=1683","date":"2026"},{"title":"Report CERT-AGID 2025","publisher":"AgID","url":"https://www.agid.gov.it/sites/agid/files/2026-02/Report%20CERT-AGID%202025.pdf","date":"febbraio 2026"}]}'::jsonb)
on conflict (slug) do update set kind = excluded.kind, sort_order = excluded.sort_order, title = excluded.title,
  summary = excluded.summary, difficulty = excluded.difficulty, category = excluded.category, roles = excluded.roles,
  estimated_minutes = excluded.estimated_minutes, content = excluded.content;

insert into public.mission_keys (mission_id, steps, debrief)
select id, '{"s1":{"correct":"b","explanation":"Isolare limita il danno e preserva lo stato per l''analisi; riavviare o spegnere può distruggere evidenze volatili.","senior":"Con un allegato aperto due volte parto dal presupposto peggiore: PC compromesso e credenziali esposte. È più sicuro ridimensionare dopo che sottovalutare prima."},"s2":{"correct":"b","explanation":"I dropper spesso non mostrano nulla o mostrano un errore: l''utente riapre il file, aumentando il danno.","senior":"Passo all''IT nome e hash dell''allegato: con quelli possono cercare se altri l''hanno ricevuto o aperto."},"s3":{"correct":"a","explanation":"Le credenziali rubate vengono spesso usate in seguito: la finestra temporale guida il controllo dei log di accesso.","senior":"Chiedo l''elenco dei servizi usati da quel PC (email, VPN, gestionale, home banking): ognuno è un possibile accesso futuro dell''attaccante."},"s4":{"correct":"hyp","explanation":"Il comportamento è tipico della famiglia, ma va confermato sull''endpoint specifico.","senior":"Distinguo ''cosa fa di solito questa famiglia'' (intelligence) da ''cosa è successo su questo PC'' (evidenza). Nel report li tengo separati."},"s5":{"explanation":"Confronta con il senior.","senior":"1) PC isolato e analizzato/reinstallato da chi gestisce gli endpoint. 2) Cambio di tutte le password salvate da un dispositivo pulito, con invalidazione delle sessioni e verifica degli accessi recenti. 3) Blocco degli indicatori e ricerca di altri destinatari dello stesso messaggio."}}'::jsonb, '{"summary":"Hai trattato il malware più comune in Italia come un incidente: contenimento, finestra temporale, distinzione tra intelligence ed evidenza.","lessons":["Un infostealer è l''inizio, non la fine: le credenziali rubate alimentano attacchi successivi.","Mai riavviare o spegnere per ''vedere se passa''.","Separare il comportamento tipico della famiglia dai fatti osservati."],"next":["Leggi la scheda ATT&CK T1555.003 e la sezione ''Come rilevarla''."]}'::jsonb from public.missions where slug = 'infostealer-ordine-fattura'
on conflict (mission_id) do update set steps = excluded.steps, debrief = excluded.debrief;

-- 02-real-cases.json · pec-compromesse-solleciti
insert into public.missions (slug, kind, sort_order, title, summary, difficulty, category, roles, estimated_minutes, content)
values ('pec-compromesse-solleciti', 'real_case', 13, 'PEC compromesse e falsi solleciti di pagamento', 'Messaggi malevoli inviati da caselle PEC reali compromesse: l''autenticazione passa, il mittente esiste, ma il messaggio distribuisce malware. Un vettore tipicamente italiano.', 'intermediate', 'phishing_investigation',
        array['CTI Analyst', 'Cybersecurity Analyst', 'GRC Analyst']::text[], 40, '{"request":{"from":"Ufficio Legale (scenario di esercitazione)","channel":"PEC inoltrata","text":"Ci è arrivata via PEC da uno studio professionale con cui abbiamo lavorato una richiesta di pagamento con un link per scaricare il documento. La PEC è valida, quindi è sicura, giusto?"},"context":"Fenomeno reale e in crescita in Italia. La PEC è una ricostruzione didattica con domini fittizi.","dossier":{"phenomenon":"Criminali che controllano caselle PEC autentiche (credenziali rubate) inviano a tutti i contatti finti solleciti di pagamento o fatture con link o allegati che installano malware come Vidar o loader come MintsLoader.","figures":[{"text":"Nel 2024 le campagne tramite PEC compromesse sono triplicate rispetto all''anno precedente, arrivando a 57 (12 per malware e 45 di phishing).","source":1},{"text":"Nel 2025 il CERT-AGID segnala la PEC come vettore in forte crescita; secondo fonti giornalistiche gli attacchi via PEC sono quasi raddoppiati (dato non verificato sul report).","source":2},{"text":"Vidar è un infostealer venduto come servizio (MaaS); le sue campagne via PEC sono riapparse in Italia dopo circa otto mesi di pausa con nuove tecniche di offuscamento (fonte secondaria).","source":3},{"text":"MintsLoader è un loader basato su PowerShell che scarica altri malware, distribuito con falsi solleciti di pagamento via PEC (fonte secondaria).","source":4}],"how_it_works":[{"step":"Furto delle credenziali di una casella PEC (spesso da infostealer precedenti)","technique":"T1078"},{"step":"Invio di messaggi ai contatti reali della casella: fiducia massima","technique":"T1534"},{"step":"Link o allegato con script che scarica il malware","technique":"T1566.002"},{"step":"Esecuzione di PowerShell e installazione dell''infostealer","technique":"T1059.001"}],"red_flags":["Messaggio inatteso da un contatto noto, con link per ''scaricare'' un documento","Testo generico non coerente con il rapporto reale","File .js, .vbs, .zip o link a servizi di file sharing"],"impact":"La fiducia nella PEC fa saltare i controlli umani: un''infezione può propagarsi a tutta la rete di contatti professionali.","defenses":["La validità della PEC prova chi ha inviato tecnicamente il messaggio, non che sia legittimo","Verificare con il mittente su un canale diverso","Avvisare il mittente che la sua casella è compromessa"]},"materials":[{"type":"sample","sample_key":"real-pec-sollecito","label":"Ricostruzione didattica della PEC (domini fittizi)"}],"steps":[{"id":"s1","title":"Apri il caso","instruction":"Crea un caso Phishing Investigation, collegalo e scrivi l''obiettivo.","module":{"href":"/investigations/new?category=phishing_investigation&title=Sollecito%20via%20PEC%20da%20casella%20compromessa","label":"Nuovo caso"},"think":["Il mittente è una vittima o un complice?","Chi altro deve essere avvisato?"],"check":{"type":"objective","min":40},"quiz":{"type":"single","prompt":"Il messaggio supera SPF, DKIM e DMARC. Cosa significa?","options":[{"value":"a","label":"Che il messaggio è sicuro"},{"value":"b","label":"Che è stato davvero inviato da quella casella: se la casella è compromessa, l''autenticazione non dice nulla sulle intenzioni"},{"value":"c","label":"Che l''autenticazione è falsificata"}]}},{"id":"s2","title":"Analizza il messaggio","instruction":"Analizza la ricostruzione nel Phishing Lab e salva l''analisi sul caso con verdetto e motivazione.","module":{"href":"/phishing?sample=real-pec-sollecito","label":"Phishing Lab"},"think":["Se l''autenticazione passa, quali altri elementi uso?"],"check":{"type":"phishing","with_verdict":true},"quiz":{"type":"multi","prompt":"Su quali elementi fondi il verdetto?","options":[{"value":"link","label":"Link per scaricare un archivio da un dominio estraneo allo studio"},{"value":"context","label":"Richiesta non coerente con il rapporto reale con lo studio"},{"value":"pec","label":"Il fatto che sia una PEC"},{"value":"generic","label":"Testo generico e urgente"}]}},{"id":"s3","title":"Tecniche e notifiche","instruction":"Mappa almeno una tecnica ATT&CK del dossier e crea un''attività nel caso per avvisare lo studio mittente tramite un canale alternativo.","module":{"href":"/investigations/{case}?tab=attack","label":"Scheda ATT&CK"},"think":["Come avviso lo studio senza usare la casella compromessa?"],"check":{"type":"attack","any_of":["T1534","T1078","T1566","T1059.001"]},"quiz":{"type":"single","prompt":"Come contatti lo studio mittente?","options":[{"value":"a","label":"Rispondendo alla PEC ricevuta"},{"value":"b","label":"Con un canale indipendente (telefono dai contatti noti, email di un referente)"}]}},{"id":"s4","title":"Report","instruction":"Crea il report con verdetto, indicatori, avviso al mittente, raccomandazioni sulla gestione delle PEC e limiti; finalizzalo.","module":{"href":"/reports/new?case={case}","label":"Nuovo report"},"think":["Quale regola pratica lascio all''ufficio legale?"],"check":{"type":"report","status":"final"},"quiz":{"type":"text","prompt":"Scrivi la regola pratica per l''ufficio legale sulle PEC inattese.","min_length":60}}],"sources":[{"title":"Report riepilogativo CERT-AGID 2024","publisher":"AgID","url":"https://www.agid.gov.it/sites/agid/files/2025-01/Report_Riepilogativo_Cert-AgID_2024.pdf","date":"gennaio 2025"},{"title":"Report CERT-AGID 2025","publisher":"AgID","url":"https://www.agid.gov.it/sites/agid/files/2026-02/Report%20CERT-AGID%202025.pdf","date":"febbraio 2026"},{"title":"Vidar: il malspam prende di mira le PEC con nuove tecniche di offuscamento","publisher":"Cybersecurity360 (fonte secondaria)","url":"https://www.cybersecurity360.it/news/vidar-il-malspam-prende-di-mira-le-pec-con-nuove-tecniche-di-offuscamento/","date":"2025"},{"title":"Falsi solleciti di pagamento, quando la truffa arriva via PEC","publisher":"Punto Informatico (fonte secondaria)","url":"https://www.punto-informatico.it/falsi-solleciti-pagamento-truffa-pec/","date":"2025"}]}'::jsonb)
on conflict (slug) do update set kind = excluded.kind, sort_order = excluded.sort_order, title = excluded.title,
  summary = excluded.summary, difficulty = excluded.difficulty, category = excluded.category, roles = excluded.roles,
  estimated_minutes = excluded.estimated_minutes, content = excluded.content;

insert into public.mission_keys (mission_id, steps, debrief)
select id, '{"s1":{"correct":"b","explanation":"SPF/DKIM/DMARC provano l''origine tecnica, non la legittimità del contenuto: una casella compromessa li supera tutti.","senior":"È la lezione più importante di questo caso: ''autenticato'' non significa ''sicuro''. Lo scrivo esplicitamente nel report perché è un errore molto diffuso."},"s2":{"correct":["context","generic","link"],"explanation":"Il canale PEC non è un indizio di frode in sé: lo sono il link estraneo, il contesto incoerente e il testo generico.","senior":"Quando gli header sono puliti, il contesto diventa la prova principale: chiedo all''ufficio se c''è davvero un pagamento in sospeso con quello studio."},"s3":{"correct":"b","explanation":"Rispondere alla casella compromessa avvisa l''attaccante e non il titolare.","senior":"Avvisare il mittente è anche un atto di collaborazione: probabilmente ha centinaia di contatti che stanno ricevendo lo stesso messaggio."},"s4":{"explanation":"Confronta con il senior.","senior":"Una PEC valida prova chi l''ha inviata, non che sia legittima: se una PEC inattesa chiede pagamenti o di scaricare file, verifica sempre per telefono con un contatto già noto prima di cliccare."}}'::jsonb, '{"summary":"Hai visto il limite dell''autenticazione email e l''importanza del contesto: un tema molto italiano e molto attuale.","lessons":["Autenticato ≠ legittimo.","Il contesto del rapporto è un''evidenza.","Avvisare il mittente su un canale indipendente."],"next":["Confronta questo caso con ''Infostealer nell''allegato ordine'': la PEC compromessa è spesso il risultato di un infostealer precedente."]}'::jsonb from public.missions where slug = 'pec-compromesse-solleciti'
on conflict (mission_id) do update set steps = excluded.steps, debrief = excluded.debrief;

-- 02-real-cases.json · clickfix-finto-captcha
insert into public.missions (slug, kind, sort_order, title, summary, difficulty, category, roles, estimated_minutes, content)
values ('clickfix-finto-captcha', 'real_case', 14, 'ClickFix: il finto CAPTCHA che fa eseguire comandi all''utente', 'Una pagina chiede di ''dimostrare di non essere un robot'' incollando un comando in Esegui o PowerShell. Tecnica in forte crescita in Italia dal 2025, usata anche con esche a tema corrieri.', 'intermediate', 'security_incident_analysis',
        array['CTI Analyst', 'Cybersecurity Analyst']::text[], 40, '{"request":{"from":"Utente del magazzino (scenario di esercitazione)","channel":"Chat interna","text":"Seguivo il link di una mail del corriere per la spedizione bloccata. Mi ha chiesto di verificare che non sono un robot premendo Windows+R e incollando un codice. L''ho fatto, poi la pagina si è chiusa. Ho sbagliato qualcosa?"},"context":"Tecnica reale e in crescita. L''email è una ricostruzione didattica con domini fittizi; il meccanismo è quello documentato dal CERT-AGID e da numerosi vendor.","dossier":{"phenomenon":"ClickFix: una pagina (raggiunta da email o da siti compromessi) mostra un finto CAPTCHA o un finto errore e spinge l''utente a copiare un comando negli strumenti di sistema. È l''utente stesso a eseguire il malware, aggirando molti controlli automatici.","figures":[{"text":"La prima campagna ClickFix in Italia è stata segnalata dal CERT-AGID a gennaio 2025; nel 2025 ne sono state censite circa 70, in forte crescita.","source":1},{"text":"A novembre 2025 il CERT-AGID ha individuato una campagna a tema GLS che usava ClickFix per installare il RAT Remcos, anche con la variante ''FileFix'' tramite Esplora file (fonte secondaria).","source":2},{"text":"Nel 2026 sono state descritte varianti più sofisticate come ''TerminalFix'' (fonte vendor).","source":3}],"how_it_works":[{"step":"Email a tema spedizione o falso errore su un sito","technique":"T1566.002"},{"step":"Il finto CAPTCHA copia negli appunti un comando malevolo","technique":"T1204.004"},{"step":"L''utente lo incolla in Esegui/PowerShell: esecuzione di script","technique":"T1059.001"},{"step":"Installazione di RAT o infostealer e connessione all''attaccante","technique":"T1219"}],"red_flags":["Nessun CAPTCHA legittimo chiede di aprire Esegui, PowerShell o il Terminale","Istruzioni a tastiera (Win+R, Ctrl+V, Invio)","Pagina che si chiude subito dopo"],"impact":"Esecuzione di codice con i permessi dell''utente: accesso remoto, furto di credenziali, base per attacchi successivi.","defenses":["Isolare subito il PC","Formazione specifica: ''nessun sito chiede di incollare comandi''","Limitare PowerShell e la finestra Esegui per gli utenti che non ne hanno bisogno"]},"materials":[{"type":"sample","sample_key":"real-clickfix-corriere","label":"Ricostruzione didattica dell''email del ''corriere'' (domini fittizi)"}],"steps":[{"id":"s1","title":"Apri il caso come incidente","instruction":"Crea un caso Security Incident Analysis, collegalo e scrivi l''obiettivo.","module":{"href":"/investigations/new?category=security_incident_analysis&title=ClickFix%20-%20comando%20eseguito%20da%20utente","label":"Nuovo caso"},"think":["L''utente ha eseguito un comando: è già compromissione?"],"check":{"type":"objective","min":40},"quiz":{"type":"single","prompt":"Perché ClickFix aggira molte difese automatiche?","options":[{"value":"a","label":"Perché è l''utente stesso a eseguire il comando, con strumenti legittimi del sistema"},{"value":"b","label":"Perché usa sempre vulnerabilità sconosciute"},{"value":"c","label":"Perché non lascia traccia"}]}},{"id":"s2","title":"Analizza l''email","instruction":"Analizza la ricostruzione nel Phishing Lab e salva l''analisi sul caso con verdetto.","module":{"href":"/phishing?sample=real-clickfix-corriere","label":"Phishing Lab"},"think":["Il link porta al sito del corriere?"],"check":{"type":"phishing","with_verdict":true},"quiz":{"type":"single","prompt":"Il comando copiato dalla pagina è un''evidenza importante. Come la gestisci?","options":[{"value":"a","label":"La faccio rieseguire all''utente per vedere cosa succede"},{"value":"b","label":"La recupero (es. dalla cronologia o dall''utente) come testo, la registro come evidenza e la passo a chi analizza l''endpoint, senza eseguirla"}]}},{"id":"s3","title":"Mappa la tecnica","instruction":"Mappa sul caso almeno una tecnica ATT&CK del dossier (es. T1204.004 o T1059.001). Leggi nella scheda come si rileva.","module":{"href":"/attack/T1059.001","label":"Scheda T1059.001"},"think":["Quali log mi direbbero cosa ha fatto il comando?"],"check":{"type":"attack","any_of":["T1204","T1059.001","T1566","T1219"]},"quiz":{"type":"single","prompt":"Quale mitigazione strutturale riduce questo rischio?","options":[{"value":"a","label":"Limitare l''uso di PowerShell/Esegui agli utenti che ne hanno bisogno, insieme a formazione mirata"},{"value":"b","label":"Disattivare i CAPTCHA su tutti i siti"}]}},{"id":"s4","title":"Report","instruction":"Crea il report con contenimento, evidenze, tecniche, raccomandazioni (tecniche e formative) e limiti; finalizzalo.","module":{"href":"/reports/new?case={case}","label":"Nuovo report"},"check":{"type":"report","status":"final"},"think":["Che messaggio di sensibilizzazione mando a tutti?"],"quiz":{"type":"text","prompt":"Scrivi il messaggio di sensibilizzazione per i colleghi (2–3 righe).","min_length":60}}],"sources":[{"title":"Report CERT-AGID 2025","publisher":"AgID","url":"https://www.agid.gov.it/sites/agid/files/2026-02/Report%20CERT-AGID%202025.pdf","date":"febbraio 2026"},{"title":"Attacco ClickFix a tema GLS per installare Remcos","publisher":"Punto Informatico (fonte secondaria)","url":"https://www.punto-informatico.it/attacco-clickfix-gls-remcos/","date":"novembre 2025"},{"title":"TerminalFix looks like ClickFix but delivers a very different payload","publisher":"Malwarebytes (vendor)","url":"https://www.malwarebytes.com/it/blog/news/2026/09/terminalfix-looks-like-clickfix-but-delivers-a-very-different-payload","date":"settembre 2026"}]}'::jsonb)
on conflict (slug) do update set kind = excluded.kind, sort_order = excluded.sort_order, title = excluded.title,
  summary = excluded.summary, difficulty = excluded.difficulty, category = excluded.category, roles = excluded.roles,
  estimated_minutes = excluded.estimated_minutes, content = excluded.content;

insert into public.mission_keys (mission_id, steps, debrief)
select id, '{"s1":{"correct":"a","explanation":"L''esecuzione avviene tramite strumenti legittimi avviati dall''utente: per molti controlli sembra un''azione normale.","senior":"Tratto il caso come compromissione confermata finché l''analisi dell''endpoint non dice il contrario: il comando è stato eseguito."},"s2":{"correct":"b","explanation":"Il comando è un''evidenza preziosa: si conserva come testo e non si esegue mai.","senior":"Il comando di solito contiene l''URL da cui scarica il malware: è l''indicatore più utile da bloccare subito."},"s3":{"correct":"a","explanation":"La combinazione di restrizioni tecniche e formazione mirata riduce drasticamente l''efficacia della tecnica.","senior":"Collego ogni raccomandazione a una mitigazione ATT&CK: rende il report più credibile verso l''IT e il management."},"s4":{"explanation":"Confronta con il senior.","senior":"Nessun sito, corriere o CAPTCHA vi chiederà mai di premere Win+R o di incollare comandi in PowerShell. Se succede, chiudete la pagina e avvisate subito la sicurezza: non è un errore vostro segnalarlo, è un errore non farlo."}}'::jsonb, '{"summary":"Hai analizzato una delle tecniche più in crescita: l''utente come esecutore inconsapevole. Il fattore umano è parte della superficie d''attacco.","lessons":["Comando eseguito = compromissione da verificare.","Il comando è un''evidenza e una fonte di IOC.","La difesa è tecnica e formativa insieme."],"next":["Leggi la scheda ATT&CK T1204.004 e le strategie di rilevamento."]}'::jsonb from public.missions where slug = 'clickfix-finto-captcha'
on conflict (mission_id) do update set steps = excluded.steps, debrief = excluded.debrief;

-- 02-real-cases.json · mirax-falsa-app-io
insert into public.missions (slug, kind, sort_order, title, summary, difficulty, category, roles, estimated_minutes, content)
values ('mirax-falsa-app-io', 'real_case', 15, 'Mirax: falso sito dell''Agenzia delle Entrate e finto aggiornamento di IO', 'Un sito che imita l''Agenzia delle Entrate spinge a installare un finto aggiornamento dell''app IO su Android: in realtà è un trojan bancario con funzioni di accesso remoto che intercetta SMS e codici OTP.', 'intermediate', 'phishing_investigation',
        array['CTI Analyst', 'Digital Risk Analyst']::text[], 35, '{"request":{"from":"Dipendente dell''ufficio commerciale (scenario di esercitazione)","channel":"Telefonata","text":"Ho ricevuto un messaggio su un rimborso dell''Agenzia delle Entrate, il sito mi ha detto di aggiornare l''app IO e ho installato il file. Uso questo telefono anche per la banca e per l''app aziendale di autenticazione."},"context":"Segnalazione recente (novembre 2026, riportata dalla stampa). Il canale con cui le vittime arrivano al sito non è specificato nelle fonti consultate: nella ricostruzione usiamo un SMS, il vettore più comune per i malware Android. Dati e domini fittizi.","dossier":{"phenomenon":"Un dominio fraudolento copia il sito dell''Agenzia delle Entrate e, se visitato da Android, propone l''installazione di un APK presentato come aggiornamento dell''app IO. Il malware (Mirax) combina funzioni di trojan bancario e di accesso remoto e intercetta SMS e codici OTP.","figures":[{"text":"La campagna è stata segnalata dal CERT-AGID a novembre 2026 secondo la stampa specializzata; la data esatta non è stata verificata sulla fonte primaria.","source":1},{"text":"La schermata del falso aggiornamento mostra la dicitura ''Verificato da Google Play Protect'' per sembrare legittima (fonte secondaria).","source":2}],"how_it_works":[{"step":"Messaggio su un rimborso fiscale con link a un dominio sosia","technique":"T1566.002"},{"step":"Il sito imita l''Agenzia delle Entrate e propone un APK","technique":"T1684.001"},{"step":"Installazione di un''app da fonte sconosciuta (side-loading)","technique":"T1204.002"},{"step":"Intercettazione di SMS/OTP e controllo remoto del dispositivo","technique":null}],"red_flags":["Aggiornamenti di app che arrivano da una pagina web e non dallo store ufficiale","Richiesta di autorizzare ''origini sconosciute'' o permessi di accessibilità","Rimborsi fiscali annunciati via messaggio con link"],"impact":"Con l''intercettazione degli OTP i criminali possono autorizzare operazioni bancarie e, su un telefono usato anche per lavoro, superare l''autenticazione a due fattori aziendale.","defenses":["Disconnettere il telefono dalla rete e non usarlo per banca e lavoro","Avvisare la banca e l''IT aziendale (revoca dei token MFA sul dispositivo)","Installare app solo dagli store ufficiali; policy MDM sui telefoni usati per lavoro"]},"materials":[{"type":"sample","sample_key":"real-mirax-sms","label":"Ricostruzione didattica del messaggio (domini fittizi)"}],"steps":[{"id":"s1","title":"Apri il caso","instruction":"Crea un caso Phishing Investigation con priorità critica, collegalo e scrivi l''obiettivo includendo il rischio per l''autenticazione aziendale.","module":{"href":"/investigations/new?category=phishing_investigation&title=Finto%20aggiornamento%20IO%20-%20malware%20Android","label":"Nuovo caso"},"think":["Perché il fatto che il telefono generi i codici MFA aziendali cambia la priorità?"],"check":{"type":"objective","min":40},"quiz":{"type":"single","prompt":"Qual è il rischio principale per l''azienda?","options":[{"value":"a","label":"Che il telefono si rompa"},{"value":"b","label":"Che l''attaccante intercetti codici OTP e superi l''autenticazione a due fattori di servizi aziendali e bancari"},{"value":"c","label":"Nessuno: è un telefono personale"}]}},{"id":"s2","title":"Analizza il messaggio","instruction":"Analizza la ricostruzione nel Phishing Lab e salva l''analisi sul caso con verdetto.","module":{"href":"/phishing?sample=real-mirax-sms","label":"Phishing Lab"},"think":["Da dove arrivano gli aggiornamenti legittimi delle app?"],"check":{"type":"phishing","with_verdict":true},"quiz":{"type":"single","prompt":"La pagina mostra ''Verificato da Google Play Protect''. Cosa ne pensi?","options":[{"value":"a","label":"È una garanzia"},{"value":"b","label":"È un elemento grafico che chiunque può inserire in una pagina web: non prova nulla"}]}},{"id":"s3","title":"Contenimento e tecniche","instruction":"Crea almeno 2 attività nel caso (es. revoca dei token MFA del dispositivo, contatto con la banca) e mappa almeno una tecnica ATT&CK.","module":{"href":"/investigations/{case}?tab=tasks","label":"Attività del caso"},"think":["Chi deve fare cosa nelle prossime 2 ore?"],"check":{"type":"tasks","min":2},"quiz":{"type":"single","prompt":"Il dipendente propone di disinstallare l''app e continuare a usare il telefono. Va bene?","options":[{"value":"a","label":"Sì, basta disinstallarla"},{"value":"b","label":"No: il dispositivo va considerato compromesso finché non viene ripristinato; nel frattempo niente banca né servizi aziendali"}]}},{"id":"s4","title":"Report","instruction":"Crea il report con contenimento, azioni per banca e IT, raccomandazioni di policy sui dispositivi mobili e limiti (fonti secondarie); finalizzalo.","module":{"href":"/reports/new?case={case}","label":"Nuovo report"},"check":{"type":"report","status":"final"},"think":["Come scrivo il limite ''data della campagna non verificata sulla fonte primaria''?"],"quiz":{"type":"text","prompt":"Scrivi la sezione ''Limitazioni'' del report.","min_length":60}}],"sources":[{"title":"Falso aggiornamento dell''app IO installa il malware Mirax","publisher":"Punto Informatico (fonte secondaria)","url":"https://www.punto-informatico.it/falso-aggiornamento-app-io-installa-malware-mirax/","date":"novembre 2026"},{"title":"Attenzione al falso sito dell''Agenzia delle Entrate: nasconde il malware Mirax per Android","publisher":"SmartWorld (fonte secondaria)","url":"https://smartworld.it/news/agenzia-entrate-falso-sito-malware-mirax-android.html","date":"novembre 2026"}]}'::jsonb)
on conflict (slug) do update set kind = excluded.kind, sort_order = excluded.sort_order, title = excluded.title,
  summary = excluded.summary, difficulty = excluded.difficulty, category = excluded.category, roles = excluded.roles,
  estimated_minutes = excluded.estimated_minutes, content = excluded.content;

insert into public.mission_keys (mission_id, steps, debrief)
select id, '{"s1":{"correct":"b","explanation":"L''intercettazione degli OTP annulla la protezione del secondo fattore su tutti i servizi gestiti dal telefono.","senior":"Su questo caso agisco in minuti, non ore: revoca dei fattori di autenticazione legati a quel dispositivo e contatto con la banca."},"s2":{"correct":"b","explanation":"Badge e diciture di sicurezza su una pagina web sono solo immagini.","senior":"La regola che lascio nel report è semplice: gli aggiornamenti arrivano solo dallo store, mai da una pagina o da un messaggio."},"s3":{"correct":"b","explanation":"Un trojan con funzioni di accesso remoto può aver installato altro o mantenere privilegi: il dispositivo va ripristinato.","senior":"Creo attività con un responsabile per ciascuna: IT (revoca MFA, verifica accessi), dipendente (banca, denuncia), sicurezza (IOC)."},"s4":{"explanation":"Confronta con il senior.","senior":"Le informazioni sulla campagna provengono da fonti giornalistiche che citano il CERT-AGID; la comunicazione originale non è stata consultata direttamente e la data esatta non è verificata. Il dispositivo non è stato analizzato: le funzioni del malware sono quelle descritte dalle fonti, non osservate direttamente."}}'::jsonb, '{"summary":"Hai gestito una minaccia mobile recente, valutando l''impatto sull''autenticazione aziendale e dichiarando con onestà i limiti delle fonti.","lessons":["Il telefono è parte del perimetro aziendale.","Gli aggiornamenti si installano solo dagli store.","Dichiara quando lavori su fonti secondarie."],"next":["Cerca sul sito del CERT-AGID la comunicazione originale su Mirax e verifica i dati del dossier."]}'::jsonb from public.missions where slug = 'mirax-falsa-app-io'
on conflict (mission_id) do update set steps = excluded.steps, debrief = excluded.debrief;

-- 02-real-cases.json · ransomware-manifatturiero
insert into public.missions (slug, kind, sort_order, title, summary, difficulty, category, roles, estimated_minutes, content)
values ('ransomware-manifatturiero', 'real_case', 16, 'Ransomware in un''azienda manifatturiera: l''accesso con credenziali valide', 'Il settore manifatturiero è il più colpito dal ransomware in Italia. Ricostruisci la sequenza di un attacco partito da credenziali VPN compromesse a partire da log simulati.', 'advanced', 'security_incident_analysis',
        array['CTI Analyst', 'Cybersecurity Analyst', 'GRC Analyst']::text[], 60, '{"request":{"from":"Direttore di stabilimento (scenario di esercitazione)","channel":"Telefonata alle 07:40","text":"Stamattina i PC dell''ufficio tecnico mostrano un messaggio che chiede un riscatto e i file hanno un''estensione strana. La produzione è ferma. Cosa sappiamo? Cosa dico alla direzione?"},"context":"Il caso è costruito su dati simulati (log fittizi), ma lo schema riflette ciò che l''ACN riporta mese per mese nel 2026: ransomware concentrato su manifattura, tecnologia e commercio, con accesso iniziale tramite credenziali valide compromesse e accessi remoti mal configurati.","dossier":{"phenomenon":"Ransomware con doppia estorsione: gli attaccanti entrano con credenziali valide (spesso rubate da infostealer o riusate), si muovono nella rete, esfiltrano dati e infine cifrano i sistemi chiedendo un riscatto per la chiave e per non pubblicare i dati.","figures":[{"text":"Ad aprile 2026 l''ACN indica credenziali valide compromesse e accessi remoti configurati male come principali vie d''ingresso; il ransomware ha colpito soprattutto manifattura, trasporti e altre imprese private.","source":1},{"text":"A settembre 2026 l''ACN ha registrato 485 eventi e 235 incidenti; il ransomware è stato la minaccia più significativa (anche contro due strutture sanitarie), con tecnologia, commercio e manifattura come settori più colpiti.","source":2},{"text":"Il Rapporto Clusit 2026 segnala la crescente pressione del cybercrime sulle imprese manifatturiere italiane (fonte secondaria per i dettagli).","source":3}],"how_it_works":[{"step":"Accesso VPN con credenziali valide rubate o riusate","technique":"T1078"},{"step":"Ricognizione della rete interna","technique":"T1046"},{"step":"Movimento laterale con desktop remoto","technique":"T1021.001"},{"step":"Esfiltrazione dei dati prima della cifratura","technique":"T1041"},{"step":"Cifratura dei sistemi e richiesta di riscatto","technique":"T1486"}],"red_flags":["Accessi VPN in orari notturni o da paesi insoliti","Uso improvviso di strumenti di amministrazione da account non amministrativi","Traffico in uscita anomalo nei giorni precedenti"],"impact":"Fermo produttivo, perdita o pubblicazione di dati, obblighi di notifica (ad esempio NIS2 per i soggetti interessati e GDPR se ci sono dati personali).","defenses":["MFA su tutti gli accessi remoti","Backup offline e testati","Monitoraggio degli accessi anomali e segmentazione della rete"]},"materials":[{"type":"text","title":"Estratto log VPN e firewall (SIMULATO)","body":"2026-11-14 03:12:44  VPN  login OK      user=m.ferraro   src=203.0.113.77  geo=estero  mfa=none\n2026-11-14 03:20:10  FW   scan          src=10.10.5.23 (VPN pool) -> 10.10.0.0/16 porte 445,3389\n2026-11-14 03:41:02  RDP  login OK      user=m.ferraro   host=SRV-FILE01\n2026-11-15 02:05:33  FW   outbound      src=SRV-FILE01 dst=198.51.100.200:443  bytes=38.4 GB\n2026-11-17 01:58:12  EDR  alert         host=SRV-FILE01 process=x.exe  ''mass file rename''\n2026-11-17 02:30:00  -    note          file con estensione .lck su 42 PC; nota di riscatto README_RESTORE.txt\n2026-11-17 07:40:00  -    segnalazione  direttore di stabilimento chiama la sicurezza\nNota HR: m.ferraro è un tecnico che usa la VPN solo in orario d''ufficio; il 2 novembre aveva segnalato ''un allegato strano'' (ticket chiuso)."}],"steps":[{"id":"s1","title":"Apri il caso critico","instruction":"Crea un caso Security Incident Analysis con priorità critica, collegalo e scrivi l''obiettivo (contenimento, perimetro, comunicazione).","module":{"href":"/investigations/new?category=security_incident_analysis&title=Ransomware%20stabilimento","label":"Nuovo caso"},"think":["Cosa deve sapere la direzione nella prossima ora?","Chi deve essere coinvolto (IT, legale, eventuali notifiche)?"],"check":{"type":"objective","min":40},"quiz":{"type":"single","prompt":"Il direttore chiede se pagare il riscatto. Qual è la risposta professionale dell''analista?","options":[{"value":"a","label":"Decidere da solo di pagare per ripartire prima"},{"value":"b","label":"Non è una decisione dell''analista: fornisce i fatti (perimetro, backup, dati esfiltrati) a direzione, legale e autorità competenti"},{"value":"c","label":"Contattare i criminali per negoziare"}]}},{"id":"s2","title":"Ricostruisci la timeline dai log","instruction":"Dal log simulato ricostruisci in timeline almeno 5 eventi (accesso, scansione, movimento laterale, esfiltrazione, cifratura), con data dell''evento e data di acquisizione.","module":{"href":"/investigations/{case}?tab=timeline","label":"Timeline"},"think":["Quando è iniziato davvero l''attacco rispetto a quando ce ne siamo accorti?","Che c''entra il ticket del 2 novembre?"],"check":{"type":"timeline","min":5},"quiz":{"type":"single","prompt":"Quanto tempo è passato tra l''accesso iniziale e la cifratura?","options":[{"value":"a","label":"Circa 3 giorni"},{"value":"b","label":"Poche ore"},{"value":"c","label":"Non si può stabilire"}]}},{"id":"s3","title":"Mappa la catena d''attacco","instruction":"Mappa sul caso almeno 3 tecniche ATT&CK della catena, con stato e confidenza coerenti con i log.","module":{"href":"/investigations/{case}?tab=attack","label":"Scheda ATT&CK"},"think":["Il log dimostra l''esfiltrazione o solo un trasferimento anomalo?"],"check":{"type":"attack","min":3},"quiz":{"type":"single","prompt":"Il trasferimento di 38 GB verso un IP esterno come lo etichetti per T1041 (esfiltrazione)?","options":[{"value":"a","label":"Fatto verificato: i dati sono stati sicuramente pubblicati"},{"value":"b","label":"Molto probabile (confidenza alta) ma da confermare: il log mostra il volume, non il contenuto"}]}},{"id":"s4","title":"Valuta il rischio e collega l''origine","instruction":"Aggiorna il livello di rischio del caso e registra un risultato OSINT sull''accesso iniziale (credenziali di m.ferraro, possibile infostealer dopo il ticket del 2 novembre) come ipotesi.","module":{"href":"/osint?case={case}","label":"OSINT Workspace"},"think":["Quale ipotesi spiega le credenziali valide?","Cosa la confermerebbe?"],"check":{"type":"risk_set"},"quiz":{"type":"single","prompt":"Quale controllo avrebbe probabilmente impedito l''accesso iniziale?","options":[{"value":"a","label":"MFA sulla VPN"},{"value":"b","label":"Un antivirus più costoso sui PC dell''ufficio tecnico"},{"value":"c","label":"Password più lunghe"}]}},{"id":"s5","title":"Brief per la direzione","instruction":"Crea un Executive Intelligence Brief: cosa è successo, cosa sappiamo e cosa no, decisioni richieste, obblighi da valutare con il legale. Finalizzalo.","module":{"href":"/reports/new?case={case}","label":"Nuovo report"},"check":{"type":"report","status":"final"},"think":["Separo fatti, stime e ignoto?"],"quiz":{"type":"text","prompt":"Scrivi l''Executive Summary per la direzione (massimo 6 righe).","min_length":150}}],"sources":[{"title":"Operational Summary ACN, aprile 2026","publisher":"ACN","url":"https://www.acn.gov.it/portale/en/w/operational-summary-acn-ad-aprile-2026-calano-eventi-e-incidenti-cyber-in-italia","date":"maggio 2026"},{"title":"Operational Summary, settembre 2026","publisher":"ACN","url":"https://www.acn.gov.it/portale/en/w/operational-summary-settembre-2026","date":"ottobre 2026"},{"title":"Rapporto Clusit 2026: cresce la pressione del cybercrime sulle imprese manifatturiere","publisher":"Computer Security News (fonte secondaria)","url":"https://www.computersecuritynews.it/rapporto-clusit-2026-in-italia-cresce-la-pressione-del-cybercrime-sulle-imprese-manifatturiere/","date":"2026"}]}'::jsonb)
on conflict (slug) do update set kind = excluded.kind, sort_order = excluded.sort_order, title = excluded.title,
  summary = excluded.summary, difficulty = excluded.difficulty, category = excluded.category, roles = excluded.roles,
  estimated_minutes = excluded.estimated_minutes, content = excluded.content;

insert into public.mission_keys (mission_id, steps, debrief)
select id, '{"s1":{"correct":"b","explanation":"Il pagamento è una decisione della direzione con valutazioni legali; l''analista fornisce fatti affidabili e tempestivi.","senior":"Nella prima ora consegno tre cose: perimetro noto (quali sistemi), stato dei backup, indizi di esfiltrazione. Senza questi dati nessuno può decidere bene."},"s2":{"correct":"a","explanation":"Accesso il 14 novembre alle 03:12, cifratura il 17 novembre: circa tre giorni in cui l''attaccante è rimasto nella rete senza essere fermato.","senior":"Il dato che colpisce la direzione è proprio questo: tre giorni di presenza non rilevata. È il ponte verso le raccomandazioni sul monitoraggio."},"s3":{"correct":"b","explanation":"Il volume e la destinazione rendono l''esfiltrazione molto probabile, ma il contenuto non è dimostrato dal log.","senior":"Mappo T1078, T1021.001 e T1486 come fatti (log e nota di riscatto), T1041 con confidenza alta ma come ''da verificare''."},"s4":{"correct":"a","explanation":"Con credenziali valide l''MFA è il controllo che interrompe l''accesso; l''antivirus non interviene su un login VPN.","senior":"Collego il ticket chiuso del 2 novembre: un possibile infostealer potrebbe aver rubato le credenziali. È un''ipotesi da verificare, ma spiega tutto ed è una lezione organizzativa."},"s5":{"explanation":"Confronta con il senior.","senior":"Attacco ransomware confermato su 42 PC e un file server. L''accesso è avvenuto il 14/11 con credenziali VPN valide di un dipendente, senza MFA; per tre giorni l''attaccante si è mosso nella rete e ha trasferito 38 GB verso l''esterno (esfiltrazione molto probabile). Da decidere oggi: ripristino da backup, valutazione con il legale degli obblighi di notifica, comunicazione a clienti e personale. Ignoto: contenuto dei dati esfiltrati."}}'::jsonb, '{"summary":"Hai trasformato log grezzi in una cronologia e in un brief decisionale: è il lavoro che un analista fa sotto pressione durante un incidente reale.","lessons":["Fatti, stime e ignoto vanno separati, soprattutto sotto pressione.","Le credenziali valide sono la porta d''ingresso più comune: MFA e monitoraggio degli accessi.","Un ticket chiuso troppo presto può essere l''inizio dell''incidente."],"next":["Leggi l''Operational Summary ACN più recente e confronta i settori colpiti con questo scenario."]}'::jsonb from public.missions where slug = 'ransomware-manifatturiero'
on conflict (mission_id) do update set steps = excluded.steps, debrief = excluded.debrief;

-- 02-real-cases.json · ddos-hacktivisti-noname
insert into public.missions (slug, kind, sort_order, title, summary, difficulty, category, roles, estimated_minutes, content)
values ('ddos-hacktivisti-noname', 'real_case', 17, 'DDoS hacktivista contro siti istituzionali: rivendicazioni e impatto reale', 'Gruppi filorussi come NoName057(16) colpiscono a ondate siti di enti pubblici, trasporti e banche italiane. Il lavoro dell''analista: distinguere rivendicazioni, impatto reale e comunicazione.', 'intermediate', 'cyber_threat_intelligence',
        array['CTI Analyst', 'OSINT Analyst']::text[], 40, '{"request":{"from":"Ufficio Comunicazione di un ente pubblico (scenario di esercitazione)","channel":"Email urgente","text":"Un canale Telegram rivendica di aver ''abbattuto'' il nostro sito stamattina e un giornalista ci chiede un commento. Il sito era davvero giù? Ci hanno rubato dati?"},"context":"Fenomeno reale e ricorrente contro l''Italia. La rivendicazione e i dati di monitoraggio sono simulati; lo schema è quello documentato da vendor e stampa per le campagne del 2026.","dossier":{"phenomenon":"DDoS di matrice hacktivista: si sovraccaricano siti pubblici per renderli irraggiungibili per qualche ora e si rivendica l''attacco sui canali del gruppo, spesso in risposta a eventi politici. In genere non c''è furto di dati.","figures":[{"text":"Tra il 2 e l''8 febbraio 2026 l''Italia è stata il primo bersaglio della campagna DDoS di NoName057(16) con lo strumento DDoSia, con circa il 43% degli attacchi osservati (fonte vendor).","source":1},{"text":"Durante le Olimpiadi Milano-Cortina 2026 il gruppo ha preso di mira siti governativi e strutture alberghiere (fonte secondaria).","source":2},{"text":"Il Rapporto Clusit 2026 colloca il DDoS tra le tecniche più rilevate in Italia (le percentuali variano tra le fonti secondarie).","source":3}],"how_it_works":[{"step":"Il gruppo pubblica una lista di bersagli ai partecipanti","technique":null},{"step":"Migliaia di richieste saturano il sito o l''applicazione","technique":"T1499"},{"step":"Rivendicazione con screenshot del sito irraggiungibile","technique":null}],"red_flags":["Picchi di richieste da molte sorgenti nello stesso momento","Rivendicazioni su canali hacktivisti in concomitanza con eventi politici"],"impact":"Indisponibilità temporanea dei servizi online e danno reputazionale; di solito nessuna compromissione dei dati, ma la comunicazione va gestita con precisione.","defenses":["Protezione anti-DDoS e CDN","Pagine statiche di emergenza","Comunicazione basata sui fatti verificati"]},"materials":[{"type":"text","title":"Dati di monitoraggio e rivendicazione (SIMULATI)","body":"Rivendicazione (canale hacktivista, 09:05): ''Il sito dell''ente è stato distrutto dai nostri attacchi!'' con screenshot di errore.\nMonitoraggio disponibilità: sito irraggiungibile 08:47–09:31 (44 minuti), tempi di risposta elevati fino alle 10:10.\nWAF/CDN: picco di 1,2 milioni di richieste/min da circa 9.000 IP, soprattutto verso la pagina di ricerca.\nSistemi interni e database: nessun accesso anomalo registrato; servizi interni regolari.\nStoria: lo stesso ente era stato elencato tra i bersagli in una campagna di febbraio 2026."}],"steps":[{"id":"s1","title":"Apri il caso CTI","instruction":"Crea un caso Cyber Threat Intelligence, collegalo e scrivi l''obiettivo (verificare impatto e preparare la comunicazione).","module":{"href":"/investigations/new?category=cyber_threat_intelligence&title=DDoS%20hacktivista%20sito%20ente","label":"Nuovo caso"},"think":["Il giornalista ha bisogno di fatti, non di supposizioni.","Cosa devo evitare di confermare senza prove?"],"check":{"type":"objective","min":40},"quiz":{"type":"single","prompt":"Che valore ha la rivendicazione del gruppo come fonte?","options":[{"value":"a","label":"Affidabile: il gruppo sa cosa ha fatto"},{"value":"b","label":"Poco affidabile sull''impatto (interesse a esagerare), utile come indicatore di attribuzione e motivazione"}]}},{"id":"s2","title":"Separa rivendicazione e fatti","instruction":"Registra nell''OSINT Workspace almeno 3 risultati: la rivendicazione (fonte poco affidabile, ''informazione contraddittoria'' o ''da verificare''), il dato di monitoraggio (fatto verificato) e l''assenza di accessi anomali ai sistemi interni.","module":{"href":"/osint?case={case}","label":"OSINT Workspace"},"think":["La rivendicazione dice ''distrutto'': cosa dicono i dati?"],"check":{"type":"finding","min":3},"quiz":{"type":"single","prompt":"Un DDoS comporta di solito furto di dati?","options":[{"value":"a","label":"Sì, sempre"},{"value":"b","label":"No: è un attacco alla disponibilità; il furto di dati richiederebbe evidenze diverse, qui assenti"}]}},{"id":"s3","title":"Timeline e tecnica","instruction":"Aggiungi in timeline almeno 2 eventi (inizio indisponibilità, rivendicazione) e mappa T1499 (Endpoint Denial of Service) o una tecnica affine.","module":{"href":"/investigations/{case}?tab=attack","label":"Scheda ATT&CK"},"think":["La rivendicazione arriva prima o dopo l''impatto?"],"check":{"type":"attack","any_of":["T1499","T1498"]},"quiz":{"type":"single","prompt":"Che differenza c''è tra T1498 e T1499?","options":[{"value":"a","label":"T1498 satura la rete, T1499 esaurisce le risorse del servizio o dell''applicazione (es. pagina di ricerca)"},{"value":"b","label":"Sono la stessa cosa"}]}},{"id":"s4","title":"Nota per la comunicazione","instruction":"Crea un Executive Intelligence Brief con i fatti verificati, ciò che non è avvenuto e un testo suggerito per la risposta al giornalista. Finalizzalo.","module":{"href":"/reports/new?case={case}","label":"Nuovo report"},"check":{"type":"report","status":"final"},"think":["La risposta è precisa senza amplificare la propaganda del gruppo?"],"quiz":{"type":"text","prompt":"Scrivi la risposta suggerita al giornalista (3–4 righe).","min_length":100}}],"sources":[{"title":"Italy and Germany under DDoS (report su NoName057(16), febbraio 2026)","publisher":"SOCRadar (vendor)","url":"https://socradar.io/blog/italy-germany-under-ddos-9-feb26/","date":"febbraio 2026"},{"title":"Pro-Russian group Noname057(16) launched DDoS attacks on Milano Cortina 2026 Winter Olympics","publisher":"Security Affairs (fonte secondaria)","url":"https://securityaffairs.com/187654/hacking/pro-russian-group-noname05716-launched-ddos-attacks-on-milano-cortina-2026-winter-olympics.html","date":"febbraio 2026"},{"title":"Rapporto Clusit 2026: i dati chiave sulla cybersecurity in Italia","publisher":"Axitea (fonte secondaria)","url":"https://www.axitea.com/it/blog/rapporto-clusit-2026-sintesi-dei-principali-dati-sulla-cybersecurity-in-italia/","date":"2026"}]}'::jsonb)
on conflict (slug) do update set kind = excluded.kind, sort_order = excluded.sort_order, title = excluded.title,
  summary = excluded.summary, difficulty = excluded.difficulty, category = excluded.category, roles = excluded.roles,
  estimated_minutes = excluded.estimated_minutes, content = excluded.content;

insert into public.mission_keys (mission_id, steps, debrief)
select id, '{"s1":{"correct":"b","explanation":"Le rivendicazioni hanno finalità propagandistiche: utili per capire chi e perché, inaffidabili sull''impatto.","senior":"Valuto la rivendicazione come fonte E per l''impatto e B per l''identità del gruppo: è un esempio perfetto di come la stessa fonte valga diversamente per dati diversi."},"s2":{"correct":"b","explanation":"Il DDoS colpisce la disponibilità; senza evidenze di accesso non si può parlare di furto di dati.","senior":"Il contrasto ''distrutto'' contro ''44 minuti di indisponibilità, nessun accesso ai dati'' è il cuore della nota per la comunicazione."},"s3":{"correct":"a","explanation":"Qui il bersaglio è la pagina di ricerca (risorse applicative): T1499 è la scelta più precisa.","senior":"La rivendicazione arriva 18 minuti dopo l''inizio: tipico. Lo annoto perché aiuta a riconoscere il modus operandi nelle prossime ondate."},"s4":{"explanation":"Confronta con il senior.","senior":"Questa mattina il sito ha subito un attacco DDoS che lo ha reso irraggiungibile per circa 45 minuti. I servizi interni e i dati non sono stati coinvolti. Il sito è di nuovo pienamente operativo e abbiamo rafforzato le protezioni."}}'::jsonb, '{"summary":"Hai separato propaganda e fatti: competenza chiave per CTI e comunicazione di crisi.","lessons":["La stessa fonte può essere affidabile su un aspetto e inaffidabile su un altro.","DDoS = disponibilità, non riservatezza.","La comunicazione va basata solo sui fatti verificati."],"next":["Apri la scheda ATT&CK T1499 e leggi mitigazioni e rilevamenti."]}'::jsonb from public.missions where slug = 'ddos-hacktivisti-noname'
on conflict (mission_id) do update set steps = excluded.steps, debrief = excluded.debrief;

-- 02-real-cases.json · bec-ceo-fraud
insert into public.missions (slug, kind, sort_order, title, summary, difficulty, category, roles, estimated_minutes, content)
values ('bec-ceo-fraud', 'real_case', 18, 'BEC e CEO fraud: il bonifico urgente del ''direttore''', 'Truffe che impersonano dirigenti o fornitori per far disporre bonifici, oggi anche con voci clonate dall''IA. Nessun malware: solo ingegneria sociale e processi deboli.', 'beginner', 'phishing_investigation',
        array['Cybersecurity Analyst', 'GRC Analyst', 'Due Diligence Analyst']::text[], 35, '{"request":{"from":"Tesoreria (scenario di esercitazione)","channel":"Email + telefonata","text":"La CEO ci ha scritto di fare oggi un bonifico riservato di 48.500 euro per un''acquisizione, e poco dopo mi ha chiamato una voce identica alla sua per sollecitare. Il bonifico non è ancora partito. Procedo?"},"context":"Fenomeno reale e in crescita. L''email è il campione ''BEC'' del Phishing Lab (dati fittizi); il riferimento alle voci clonate riflette quanto riportato dalla Polizia Postale e dalla stampa.","dossier":{"phenomenon":"Business Email Compromise: l''attaccante impersona un dirigente o un fornitore (con domini sosia, caselle compromesse o webmail gratuite) e chiede un pagamento urgente e riservato. Nelle varianti recenti la richiesta è rafforzata da chiamate con voce clonata.","figures":[{"text":"Il report 2025 della Polizia Postale indica BEC e CEO fraud tra le minacce persistenti per le imprese, insieme a phishing, vishing e smishing (fonte secondaria).","source":1},{"text":"La stampa riporta casi di truffe con voce del dirigente clonata tramite IA (fonte secondaria).","source":2}],"how_it_works":[{"step":"Ricognizione dell''organigramma e dei rapporti con i fornitori","technique":"T1591.004"},{"step":"Email che impersona la CEO con risposte dirottate verso una casella dell''attaccante","technique":"T1684.001"},{"step":"Telefonata con voce clonata per aumentare la pressione","technique":null},{"step":"Bonifico verso un conto controllato dai criminali","technique":"T1657"}],"red_flags":["Urgenza e riservatezza (''non parlarne con nessuno'')","Canale insolito o Reply-To diverso","Coordinate bancarie nuove","La persona non è raggiungibile sui canali abituali"],"impact":"Perdite economiche dirette, spesso difficili da recuperare se non si agisce entro poche ore.","defenses":["Procedura di doppia verifica dei pagamenti su un canale noto (richiamare un numero già in rubrica)","Parola d''ordine o codice per le richieste urgenti","Formazione specifica di tesoreria e amministrazione"]},"materials":[{"type":"sample","sample_key":"bec","label":"Campione ''Business Email Compromise'' (dati fittizi)"}],"steps":[{"id":"s1","title":"Ferma il pagamento e apri il caso","instruction":"Crea un caso Phishing Investigation, collegalo e scrivi l''obiettivo. Prima azione (fuori dalla piattaforma): il bonifico non parte finché non c''è verifica.","module":{"href":"/investigations/new?category=phishing_investigation&title=Richiesta%20di%20bonifico%20urgente%20-%20sospetta%20CEO%20fraud","label":"Nuovo caso"},"think":["Come verifico la richiesta senza usare i canali che mi ha dato l''attaccante?"],"check":{"type":"objective","min":40},"quiz":{"type":"single","prompt":"Come verifichi la richiesta?","options":[{"value":"a","label":"Rispondendo all''email"},{"value":"b","label":"Richiamando il numero da cui è arrivata la telefonata"},{"value":"c","label":"Contattando la CEO su un canale già noto (numero in rubrica aziendale, di persona)"}]}},{"id":"s2","title":"Analizza l''email","instruction":"Analizza il campione ''BEC'' nel Phishing Lab e salva l''analisi sul caso con verdetto.","module":{"href":"/phishing?sample=bec","label":"Phishing Lab"},"think":["L''autenticazione passa: perché è comunque sospetta?"],"check":{"type":"phishing","with_verdict":true},"quiz":{"type":"multi","prompt":"Quali segnali indicano BEC in questo messaggio?","options":[{"value":"reply","label":"Reply-To su una webmail gratuita"},{"value":"domain","label":"Dominio del mittente simile ma diverso da quello aziendale"},{"value":"secret","label":"Richiesta di riservatezza e urgenza"},{"value":"attach","label":"Allegato malevolo"}]}},{"id":"s3","title":"Tecniche e processo","instruction":"Mappa almeno una tecnica (es. T1684.001 o T1657) e crea un''attività per proporre una procedura di doppia verifica dei pagamenti.","module":{"href":"/investigations/{case}?tab=attack","label":"Scheda ATT&CK"},"think":["Quale controllo di processo avrebbe fermato la truffa anche se la voce era perfetta?"],"check":{"type":"attack","any_of":["T1684.001","T1657","T1585.002","T1591"]},"quiz":{"type":"single","prompt":"Perché la BEC è un problema di processo oltre che tecnico?","options":[{"value":"a","label":"Perché non usa malware: la difesa più efficace è una procedura di verifica che nessuna urgenza può saltare"},{"value":"b","label":"Perché la tecnologia non serve a niente"}]}},{"id":"s4","title":"Report e raccomandazioni","instruction":"Crea il report con verdetto, azioni (bonifico bloccato, avviso alla CEO) e raccomandazione di processo; finalizzalo.","module":{"href":"/reports/new?case={case}","label":"Nuovo report"},"check":{"type":"report","status":"final"},"think":["Se il bonifico fosse già partito, cosa andrebbe fatto entro un''ora?"],"quiz":{"type":"text","prompt":"Se il bonifico fosse già partito: cosa fai nella prima ora?","min_length":80}}],"sources":[{"title":"Report annuale Polizia Postale 2025: la normalità dell''attacco, il dovere della resilienza","publisher":"Cybersecurity360 (fonte secondaria)","url":"https://www.cybersecurity360.it/news/report-annuale-polizia-postale-2025-la-normalita-dellattacco-il-dovere-della-resilienza/","date":"gennaio 2026"},{"title":"Ti chiama il tuo capo ma non è lui: le truffe con voce clonata","publisher":"Panorama (fonte secondaria)","url":"https://www.panorama.it/attualita/cyber-security/ti-chiama-il-tuo-capo-ma-non-e-lui-tutte-le-truffe-con-voce-clonata-che-stanno-svuotando-i-conti","date":"2026"}]}'::jsonb)
on conflict (slug) do update set kind = excluded.kind, sort_order = excluded.sort_order, title = excluded.title,
  summary = excluded.summary, difficulty = excluded.difficulty, category = excluded.category, roles = excluded.roles,
  estimated_minutes = excluded.estimated_minutes, content = excluded.content;

insert into public.mission_keys (mission_id, steps, debrief)
select id, '{"s1":{"correct":"c","explanation":"Si verifica solo su canali indipendenti e già noti: email e numero ricevuti potrebbero essere controllati dall''attaccante.","senior":"La prima frase che dico alla tesoreria: ''il bonifico non parte finché non parlo io con la CEO su un canale che conosciamo già''."},"s2":{"correct":["domain","reply","secret"],"explanation":"Non c''è alcun allegato: la BEC funziona senza malware, con impersonificazione e pressione psicologica.","senior":"Faccio notare che SPF/DKIM passano: il dominio è dell''attaccante, quindi l''autenticazione è ''corretta''. Conta il dominio, non il nome visualizzato."},"s3":{"correct":"a","explanation":"Una procedura obbligatoria di verifica rende inefficace anche l''impersonificazione più convincente.","senior":"Propongo una regola semplice: ogni nuovo IBAN o pagamento urgente sopra una soglia richiede una telefonata di conferma a un numero già in anagrafica."},"s4":{"explanation":"Confronta con il senior.","senior":"Chiamare subito la propria banca per richiamare il bonifico, che contatterà la banca ricevente; denunciare alla Polizia Postale; conservare email, numeri e orari; verificare se altre richieste simili sono arrivate ad altri uffici."}}'::jsonb, '{"summary":"Hai visto un attacco senza malware dove la difesa principale è un processo. È un caso perfetto per profili GRC e giuridici.","lessons":["Verifica sempre su un canale indipendente e già noto.","L''autenticazione email non protegge da domini sosia.","Nelle frodi i minuti contano: procedura di richiamo del bonifico."],"next":["Scrivi una bozza di procedura di verifica dei pagamenti come esercizio GRC."]}'::jsonb from public.missions where slug = 'bec-ceo-fraud'
on conflict (mission_id) do update set steps = excluded.steps, debrief = excluded.debrief;
